MW=re.compile(r"^(individual |partial |general |collective |container )?(measure word|classifier)",re.I)
def themes_for(en,word):
    en=en.split('②')[0].replace('①','')
    first=en.split(';')[0]
    if MW.match(first.strip()):
        return ['numbers']+(['animals'] if re.search(r'animal',first) else [])
    e=' '+first.lower()+' '
    out=[]
    for key,_,_,_,rx,zhs,ex in TH:
        e2=re.sub(ex,' ',e) if ex else e
        if re.search(rx,e2) or any(z==word for z in zhs): out.append(key)
    return out
def build():
    meta=[dict(key=k,seal=sl,zh=z,en=n) for k,sl,z,n,*_ in TH]
    order={'tocfl':['tocfl-a','tocfl-L3','tocfl-L4','tocfl-L5'],'hsk':[f'hsk-{i}' for i in range(1,8)]}
    LV={'Pre-A1':0,'A1':1,'A2':2,'B1':3,'B2':4,'C1–C2':5}
    for test,decks in order.items():
        out={m['key']:[] for m in meta}; seen=set()
        for d in decks:
            for c in json.load(open(f'data/{d}.json')):
                for i,w in enumerate(c['words']):
                    main=w.get('s') or w['t'].split('/')[0]
                    for th in themes_for(w['en'],main):
                        k=(th,main,w['p'])
                        if k in seen: continue
                        seen.add(k)
                        x={a:w[a] for a in ('t','s','p','en','lv','pos','f') if a in w}
                        x['d']=d;x['n']=c['n'];x['r']=LV[w['lv']] if test=='tocfl' else int(w['lv'][4])-1
                        out[th].append(x)
        for th in out: out[th].sort(key=lambda x:x['r'])
        json.dump({'themes':[m|{'count':len(out[m['key']])} for m in meta],'words':out},open(f'data/themes-{test}.json','w'),ensure_ascii=False,separators=(',',':'))
        print(test,{k:len(v) for k,v in out.items()})
if __name__=='__main__' and False:
    meta=[dict(key=k,seal=s,zh=z,en=n) for k,s,z,n,*_ in TH]
    allw=collections.defaultdict(list)
    for f in sorted(glob.glob('data/*.json')):
        k=f.split('/')[-1][:-5];test='hsk' if k.startswith('hsk') else 'tocfl'
        for c in json.load(open(f)):
            for i,w in enumerate(c['words']):
                main=w.get('s') or w['t'].split('/')[0]
                for th in themes_for(w['en'],main): allw[(test,th)].append((k,c['n'],i,main,w['en'][:30],w['lv']))
    for (t,th),ws in sorted(allw.items()):
        if t=='tocfl': print(t,th,len(ws),' | '.join(f'{m}:{e}' for _,_,_,m,e,lv in ws if lv in('Pre-A1','A1'))[:700]);print()
    print({f'{t}-{th}':len(v) for (t,th),v in allw.items() if t=='hsk'})

build()
